mapper.select:
select distinct u.user_id, coalesce(nullif(trim(u.nick_name), ''), nullif(trim(u.user_name), ''), '姓名未配置') user_name, u.dept_id, user_dept.dept_name, null post_sort from sys_dept anchor join sys_dept leader_dept on leader_dept.dept_id = anchor.dept_id or find_in_set(leader_dept.dept_id, anchor.ancestors) join sys_user u on u.user_id = leader_dept.leader_user_id left join sys_dept user_dept on user_dept.dept_id = u.dept_id left join sys_user_profile profile on profile.user_id = u.user_id where anchor.dept_id = #{anchorDeptId} and anchor.del_flag = '0' and anchor.status = '0' and leader_dept.del_flag = '0' and leader_dept.status = '0' and
and leader_dept.dept_type = #{deptType}
order by case when leader_dept.dept_id = anchor.dept_id then 9999 else find_in_set(leader_dept.dept_id, anchor.ancestors) end desc, u.user_id

select u.user_id, coalesce(nullif(trim(u.nick_name), ''), nullif(trim(u.user_name), ''), '姓名未配置') user_name, u.dept_id, d.dept_name, null post_sort from sys_user u left join sys_dept d on d.dept_id = u.dept_id left join sys_user_profile profile on profile.user_id = u.user_id where and u.user_id in
#{userId}
order by field(u.user_id, #{userId})

select distinct u.user_id, coalesce(nullif(trim(u.nick_name), ''), nullif(trim(u.user_name), ''), '姓名未配置') user_name, u.dept_id, user_dept.dept_name, p.post_sort from sys_user u join sys_user_post up on up.user_id = u.user_id join sys_post p on p.post_id = up.post_id join sys_user_shop us on us.user_id = u.user_id join sys_dept scope_dept on scope_dept.dept_id = us.dept_id join sys_dept anchor on anchor.dept_id = #{anchorDeptId} left join sys_dept user_dept on user_dept.dept_id = u.dept_id left join sys_user_profile profile on profile.user_id = u.user_id where and p.status = '0' and anchor.del_flag = '0' and anchor.status = '0' and anchor.dept_type = 'STORE' and scope_dept.del_flag = '0' and scope_dept.status = '0' and (scope_dept.dept_id = anchor.dept_id or find_in_set(scope_dept.dept_id, anchor.ancestors)) and p.post_sort > #{executiveBoundarySort} and p.post_sort < #{managerPostSort} and p.post_code not in
#{postCode}
order by p.post_sort desc, u.user_id
